# A dictionary is much cleaner for base pairing mapping
COMPLEMENT_MAP = {
    'A': 'T',
    'T': 'A',
    'C': 'G',
    'G': 'C',
}

def reverse_complement(dna_sequence):
    # 1. Reverse the sequence using Python slicing [::-1]
    reversed_sequence = dna_sequence[::-1]
    
    # 2. Build the complement string
    complement_sequence = []
    for base in reversed_sequence:
        if base in COMPLEMENT_MAP:
            complement_sequence.append(COMPLEMENT_MAP[base])
        else:
            print(f"Invalid character '{base}' in DNA sequence")
            return None # Or handle the error as desired
            
    # 3. Join the list back into a single string
    return "".join(complement_sequence)

# --- Test Case ---
if __name__ == "__main__":
    dna = "AAAACCCGGT"
